args.sparql:
SELECT ?film ?filmLabel ?director ?birthDate WHERE {
  VALUES ?film { dbr:The_King_on_Main_Street <http://dbpedia.org/resource/The_Crime_Doctor%27s_Diary> }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?bd1 }
  OPTIONAL { ?director dbp:birthDate ?bd2 }
  BIND(COALESCE(?bd1, ?bd2) AS ?birthDate)
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel) = "en") }
}
ORDER BY ?birthDate
LIMIT 1

